/**
 * M-F1: MINUS-inside-EXISTS guard pins. The proposed "uncorrelated Difference" narrowing is <b>disproven</b>: RDF4J's
 * generic evaluation flows the outer solution into BOTH arms of a Difference inside an EXISTS witness, so a right
 * solution that binds nothing of its own still inherits the outer bindings — its domain intersects every left solution
 * and it removes everything. Syntactic name-uncorrelatedness is therefore not evaluation-uncorrelatedness, and the
 * native witness route (whose MinusCursor clears non-base slots before evaluating the right arm) would diverge from the
 * oracle on exactly these shapes. The guard's assured-shared-names rule is precisely calibrated to this: these tests
 * freeze both the oracle answers and the guard's decline behavior.
 */
public class LmdbNativeMinusInsideExistsTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI person = vf.createIRI(EX, "Person");
			conn.add(vf.createIRI(EX, "s1"), RDF.TYPE, person);
			conn.add(vf.createIRI(EX, "s2"), RDF.TYPE, person);
			conn.add(vf.createIRI(EX, "s1"), vf.createIRI(EX, "q"), vf.createIRI(EX, "v1"));
			conn.add(vf.createIRI(EX, "a1"), vf.createIRI(EX, "t"), vf.createIRI(EX, "b1"));
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private List<String> subjects(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(row -> row.getValue("s").stringValue().substring(EX.length()))
					.sorted()
					.collect(Collectors.toList());
		}
	}

	/**
	 * The disproof witness: the Difference shares no variable name with the outer scope, yet the outer solution flows
	 * into its right arm, whose inherited domain then removes every left solution — the oracle answer is EMPTY, not
	 * "the empty-domain right solution removes nothing". The guard must keep declining this shape (a native
	 * clear-non-base-slots evaluation would answer s1).
	 */
	@Test
	public void nameUncorrelatedNullableSharedMinusStaysOnTheScopedEvaluator() {
		String query = "SELECT ?s WHERE { ?s a <" + EX + "Person> . FILTER EXISTS { ?s <" + EX + "q> ?v ."
				+ " { ?a <" + EX + "t> ?b } MINUS { OPTIONAL { ?a <" + EX + "nope> ?w } } } }";
		assertThat(subjects(query)).isEmpty();
	}

	/** Outer-name-correlated variant: same oracle answer (empty), same decline. */
	@Test
	public void correlatedNullableSharedMinusInsideExistsKeepsTheBroadGuard() {
		String query = "SELECT ?s WHERE { ?s a <" + EX + "Person> . FILTER EXISTS {"
				+ " { ?s <" + EX + "q> ?v } MINUS { OPTIONAL { ?s <" + EX + "nope> ?w } } } }";
		assertThat(subjects(query)).isEmpty();
	}

	/** Fully-assured shared names inside EXISTS keep compiling natively (the case the guard already admits). */
	@Test
	public void assuredSharedMinusInsideExistsStaysAdmitted() {
		String query = "SELECT ?s WHERE { ?s a <" + EX + "Person> . FILTER EXISTS {"
				+ " { ?a <" + EX + "t> ?b } MINUS { ?a <" + EX + "q> ?c } } }";
		long declinesBefore = LmdbNativeAggregateCompiler.EXISTS_SCOPE_DECLINES.get();
		assertThat(subjects(query)).containsExactly("s1", "s2");
		assertThat(LmdbNativeAggregateCompiler.EXISTS_SCOPE_DECLINES.get())
				.as("assured shared names never trip the guard")
				.isEqualTo(declinesBefore);
	}
}
